set localPath(localPath) {
  this.setFileValue("directory-rel", "directory", localPath);
}

get rootFolder() {
  if (!this._rootFolder) {
    if (Services.prefs.getBoolPref("mail.panorama.enabled", false)) {
      const core = Cc["@mozilla.org/mailnews/database-core;1"].getService(
        Ci.nsIDatabaseCore
      );
      const folders = core.folderDB;

      const root =
        folders.getFolderChildNamed(0, this._key) ||
        folders.insertRoot(this._key);
      this._rootFolder = Cc[
        "@mozilla.org/mail/folder;1?name=mailbox"
      ].createInstance(Ci.nsIMsgFolder);
      this._rootFolder.initWithFolderId(root);

      this.createDefaultMailboxes?.();
      this.setFlagsOnDefaultMailboxes?.();
    } else {
      this._rootFolder = MailServices.folderLookup.getOrCreateFolderForURL(
        this.serverURI
      );
    }
  }
  return this._rootFolder;
}

